<template>
  <el-menu
    default-active="1-4-1"
    class="el-menu-vertical-demo"
    @open="handleOpen"
    @close="handleClose"
    :collapse="isCollapse"
    background-color="#545c64"
    text-color="#fff"
    active-text-color="#ffd04b"
  >
    <h3 class="H3">{{ isCollapse ? "" : "入侵检测系统" }}</h3>
    <el-menu-item
      v-for="item in noChildren"
      :key="item.name"
      :index="item.name"
      @click="clickMenu(item)"
    >
      <i :class="`el-icon-${item.icon}`"></i>
      <span slot="title">{{ item.label }}</span>
    </el-menu-item>
  </el-menu>
</template>

<script>
export default {
  data() {
    return {
      menuData: [
        {
          path: "/",
          name: "setting",
          label: "首页",
          icon: "s-home",
          url: "Setting/Setting",
        },
        {
          path: "/chart",
          name: "chart",
          label: "流量分析",
          icon: "video-play",
          url: "Chart/Chart",
        },
        {
          path: "/table",
          name: "table",
          label: "流量检测",
          icon: "user",
          url: "Table/Table",
        },
      ],
    };
  },

  methods: {
    handleOpen(key, keyPath) {
      console.log(key, keyPath);
    },
    handleClose(key, keyPath) {
      console.log(key, keyPath);
    },
    clickMenu(item) {
      if (
        this.$router.path !== item.path &&
        !(this.$router.path === "/home" && item.path === "/")
      ) {
        this.$router.push({ path: item.path }).catch(() => console.log(1));
      }
    },
  },
  computed: {
    //没有子菜单
    noChildren() {
      return this.menuData.filter((item) => !item.children);
    },
    isCollapse() {
      return this.$store.state.tab.isCollapsed;
    },
  },
};
</script>

