<template>
  <div id="main3" style="width: auto; height: 250px"></div>
</template>

<script>
import * as echarts from "echarts";

export default {
  data() {
    return {};
  },
  sockets: {
    pr_count(data) {
      this.$store.commit("getPrCount", data);
    },
  },
  computed: {
    returnData() {
      return this.$store.state.Data.PrCount;
    },
    predictions() {
      return this.returnData.map((item) => {
        return {
          value: item.pcount,
          name: item.prediction,
        };
      });
    },
  },

  mounted() {
    this.initChart();
  },
  methods: {
    initChart() {
      const chartDom = document.getElementById("main3");
      this.chart = echarts.init(chartDom);
      this.updateChart();
    },
    updateChart() {
      const option = {
        title: {
          text: "预测结果比例",
          left: "center",
        },
        tooltip: {
          trigger: "item",
        },
        legend: {
          orient: "vertical",
          left: "left",
        },
        series: [
          {
            name: "Access From",
            type: "pie",
            radius: "50%",
            data: this.predictions,
            emphasis: {
              itemStyle: {
                shadowBlur: 10,
                shadowOffsetX: 0,
                shadowColor: "rgba(0, 0, 0, 0.5)",
              },
            },
          },
        ],
      };
      this.chart.setOption(option, true);
    },
  },
  watch: {
    immediate: true,
    predictions(newVal, oldVal) {
      if (newVal !== oldVal) {
        this.updateChart();
      }
    },
  },
};
</script>

