<template>
  <div id="main2" style="width: auto; height: 350px">{{ formattedDates }}</div>
</template>

<script>
import * as echarts from "echarts";
import moment from "moment";
export default {
  data() {
    return {
      timestamp: [],
      timeCount: [],
      chart: [],
    };
  },
  sockets: {
    time_count(data) {
      this.$store.commit("getTimeCount", data);
    },
  },
  computed: {
    returnData() {
      return this.$store.state.Data.timeCount;
    },
    eventCounts() {
      return this.returnData.map((item) => item.timeCount);
    },
    AllTime() {
      return this.returnData.map((item) => item.timestamp);
    },
    formattedDates() {
      return this.AllTime.map((timestamp, index) => {
        return {
          time: moment(timestamp, "DD/MM/YYYY hh:mm:ss a", "zh-cn").format(
            "MM/DD hh:mm:ss"
          ),
          data: this.eventCounts[index],
        };
      });
    },
  },
  mounted() {
    this.initChart();
  },
  methods: {
    initChart() {
      const chartDom = document.getElementById("main2");
      this.chart = echarts.init(chartDom);
      this.updateChart();
    },
    updateChart() {
      const option = {
        tooltip: {
          trigger: "axis",
          position: function (pt) {
            return [pt[0], "10%"];
          },
        },
        title: {
          left: "center",
          text: "实时数据请求",
        },
        toolbox: {
          feature: {
            dataZoom: {
              yAxisIndex: "none",
            },
            restore: {},
            saveAsImage: {},
          },
        },
        xAxis: {
          type: "category",
          boundaryGap: false,
        },
        yAxis: {
          type: "value",
          boundaryGap: [0, "100%"],
        },
        dataZoom: [
          {
            type: "inside",
            start: 0,
            end: 20,
          },
          {
            start: 0,
            end: 20,
          },
        ],
        series: [
          {
            name: "访问次数",
            type: "line",
            smooth: true,
            symbol: "none",
            areaStyle: {},
            data: this.formattedDates.map((item) => [item.time, item.data]),
          },
        ],
      };
      this.chart.setOption(option, true);
    },
  },
  watch: {
    // 监视 returnData，当数据更新时重新设置图表数据
    formattedDates: {
      handler(newData) {
        if (this.chart) {
          // 确保图表实例存在
          this.chart.setOption({
            series: [
              {
                data: newData.map((item) => [item.time, item.data]),
              },
            ],
          });
        }
      },
      deep: true, // 设置深度监听，以便能够检测到对象内部值的变化
    },
  },
};
</script>

<style scoped lang="less"></style>
