<template>
  <div>
    <el-table
      :data="paginatedData"
      style="width: 100%"
      max-height="700"
      :default-sort="{ prop: 'id', order: 'descending' }"
    >
      <el-table-column prop="id" label="ID" sortable width="80">
      </el-table-column>
      <el-table-column prop="timestamp" label="时间"> </el-table-column>
      <el-table-column prop="srcIp" label="源地址"> </el-table-column>
      <el-table-column prop="srcPort" label="源端口"> </el-table-column>
      <el-table-column prop="dstIp" label="目标地址"> </el-table-column>
      <el-table-column prop="dstPort" label="目标端口"> </el-table-column>
      <el-table-column prop="protocol" label="协议(6:TCP;17:UDP)">
      </el-table-column>
      <el-table-column prop="prediction" label="预测(0:正常;1:异常)">
      </el-table-column>
      <el-table-column label="操作">
        <template slot-scope="scope">
          <el-button size="mini" @click="openEditDialog(scope.row)"
            >编辑</el-button
          >
          <el-button
            size="mini"
            type="danger"
            @click="handleDelete(scope.$index, scope.row)"
            >删除</el-button
          >
        </template>
      </el-table-column>
    </el-table>

    <!-- 编辑弹出框 -->
    <el-dialog title="编辑数据" :visible.sync="editDialogVisible">
      <el-form :model="editFormData" label-width="120px">
        <el-row :gutter="20">
          <el-col :span="12">
            <el-form-item label="时间">
              <el-input
                v-model="editFormData.timestamp"
                placeholder="请输入时间"
                clearable
              ></el-input>
            </el-form-item>
          </el-col>
          <el-col :span="12">
            <el-form-item label="源地址">
              <el-input
                v-model="editFormData.srcIp"
                placeholder="请输入源地址"
                clearable
              ></el-input>
            </el-form-item>
          </el-col>
        </el-row>
        <el-row :gutter="20">
          <el-col :span="12">
            <el-form-item label="源端口">
              <el-input
                v-model="editFormData.srcPort"
                placeholder="请输入源端口"
                clearable
              ></el-input>
            </el-form-item>
          </el-col>
          <el-col :span="12">
            <el-form-item label="目标地址">
              <el-input
                v-model="editFormData.dstIp"
                placeholder="请输入目标地址"
                clearable
              ></el-input>
            </el-form-item>
          </el-col>
        </el-row>
        <el-row :gutter="20">
          <el-col :span="12">
            <el-form-item label="目标端口">
              <el-input
                v-model="editFormData.dstPort"
                placeholder="请输入目标端口"
                clearable
              ></el-input>
            </el-form-item>
          </el-col>
          <el-col :span="12">
            <el-form-item label="协议">
              <el-input
                v-model="editFormData.protocol"
                placeholder="请输入协议"
                clearable
              ></el-input>
            </el-form-item>
          </el-col>
        </el-row>
        <el-row :gutter="20">
          <el-col :span="24">
            <el-form-item label="预测">
              <el-input
                v-model="editFormData.prediction"
                placeholder="请输入预测"
                clearable
              ></el-input>
            </el-form-item>
          </el-col>
        </el-row>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="editDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="submitEditForm">保存</el-button>
      </span>
    </el-dialog>
    <el-pagination
      @size-change="handleSizeChange"
      @current-change="handleCurrentChange"
      class="pagination"
      :current-page="currentPage"
      background
      :page-size="pageSize"
      layout="total, prev, pager, next, jumper"
      :total="returnData.length"
    >
    </el-pagination>
  </div>
</template>

<script>
import axios from "axios";

export default {
  sockets: {
    data_update(data) {
      this.$store.commit("reserveData", data);
    },
  },
  computed: {
    returnData() {
      return this.$store.state.Data.allData;
    },
    paginatedData() {
      const start = (this.currentPage - 1) * this.pageSize;
      const end = start + this.pageSize;
      return this.returnData.slice(start, end);
    },
  },
  data() {
    return {
      currentPage: 1,
      pageSize: 12,
      editDialogVisible: false,
      editFormData: {
        id: null,
        timestamp: "",
        srcIp: "",
        srcPort: "",
        dstIp: "",
        dstPort: "",
        protocol: "",
        prediction: "",
      },
    };
  },
  methods: {
    handleSizeChange(val) {
      this.pageSize = val;
    },
    handleCurrentChange(val) {
      this.currentPage = val;
    },
    openEditDialog(row) {
      this.editFormData = { ...row }; // Clone the row data into the form data
      this.editDialogVisible = true;
    },
    async submitEditForm() {
      try {
        const response = await axios.put(
          `http://localhost:5000/update/${this.editFormData.id}`,
          this.editFormData
        );
        this.editDialogVisible = false;
        this.$message({
          type: "success",
          message: "Edit successful!",
        });
        // Optionally update the local data with the response data
        const index = this.returnData.findIndex(
          (item) => item.id === this.editFormData.id
        );
        if (index !== -1) {
          this.$set(this.returnData, index, response.data);
        }
      } catch (error) {
        console.error("Error editing entry:", error);
        this.$message({
          type: "error",
          message: "Edit failed!",
        });
      }
    },
    async handleDelete(index, row) {
      try {
        await axios.delete(`http://localhost:5000/delete/${row.id}`);
        this.returnData.splice(index, 1); // Remove the item from the data array
        this.$message({
          showClose: true,
          type: "success",
          message: "Delete successful!",
        });
      } catch (error) {
        console.error("Error deleting entry:", error);
        this.$message({
          showClose: true,
          type: "error",
          message: "Delete failed!",
        });
      }
    },
  },
};
</script>

<style lang="less" scoped>
.pagination {
  display: flex;
  justify-content: center;
}
</style>
